CREATE TABLE `KPI_RESULT` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '员工工号',
  `cycle_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '周期类型：MONTHLY/QUARTERLY',
  `cycle_date` date NOT NULL COMMENT '周期日期(如月末)',
  `as_of_date` date NOT NULL COMMENT '计算基准日(每日一算区分键)',
  `data_version` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '指标数据版本',
  `kpi_total_score` decimal(10,4) NOT NULL COMMENT 'KPI总分',
  `detail_json` longtext COLLATE utf8mb4_general_ci COMMENT '明细(JSON，可选)',
  `calculated_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '计算时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_cycle_asof` (`emp_id`,`cycle_type`,`cycle_date`,`as_of_date`),
  KEY `idx_as_of_date` (`as_of_date`)
) ENGINE=InnoDB AUTO_INCREMENT=10440 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='KPI结果表';
