DROP TABLE IF EXISTS `LOAN_APPLY`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `LOAN_APPLY` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请ID(UUID)',
  `apply_no` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请编号(LA+yyyyMMdd+6位序号)',
  `cust_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户ID,逻辑外键→cust_master.id',
  `source_touch_task_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源触达任务ID,逻辑外键→touch_task.id',
  `project_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '项目类型(字典PROJECT_TYPE)',
  `biz_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务类型(字典BIZ_TYPE)',
  `guarantee_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '担保方式(字典GUARANTEE_TYPE)',
  `credit_amount` decimal(20,4) DEFAULT NULL COMMENT '授信金额(元,保留4位小数)',
  `credit_exposure_amount` decimal(20,4) DEFAULT NULL COMMENT '敞口金额(元,保留4位小数)',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态:DRAFT/IN_APPROVAL/COMPLETED/REJECTED/CANCELLED',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程业务键,固定格式LOAN:{id}',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例ID,对应ACT_RU_EXECUTION/ACT_HI_PROCINST',
  `owner_org_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '归属机构(ORG_CODE),用于数据范围过滤',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人工号(PT_USER.emp_id)',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人工号',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除:0=未删,1=已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_no` (`apply_no`),
  KEY `idx_cust_id` (`cust_id`),
  KEY `idx_owner_org` (`owner_org_id`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_status` (`status`),
  KEY `idx_business_key` (`business_key`),
  KEY `idx_created_time` (`created_time`),
  KEY `idx_process_inst` (`process_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='资产投放申请表';
